package com.openggf.game.soniccd.level;
import com.openggf.game.soniccd.media.CdProgramAssets;
import com.openggf.game.soniccd.media.CdMmdImage;
import com.openggf.game.soniccd.*;import com.openggf.game.soniccd.objects.*;import org.junit.jupiter.api.BeforeAll;import org.junit.jupiter.api.Test;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.junit.jupiter.api.Assumptions.assumeTrue;
/** Actual source-backed DATA contracts, all Java UNRUN. */
class TestCdProgrammeTtSwingSource {
 static CdProgrammeObjectSource source;static CdMmdImage original;
 @BeforeAll static void open()throws Exception{String root=System.getProperty("soniccd.media.root","");Path cue=Path.of(root,"USA","Sonic CD (US).cue");assumeTrue(!root.isBlank()&&Files.isRegularFile(cue));try(var a=CdProgramAssets.open(cue,Optional.of(CdReleaseVariant.USA),Optional.empty())){source=CdProgrammeData.open(a,CdR4DataLayout.Programme.R41A).objectSource();original=a.mmd(CdNativeFile.R41A);}}
 @Test void actualSwingAndLinkedSwitchDispatchAndMappingOperandsRemainDistinct(){assertEquals(0x20CF84L,source.view(CdProgrammeObjectSource.Table.DISPATCH).bytes().unsignedLong(40*4));assertEquals(0x20CB7EL,source.view(CdProgrammeObjectSource.Table.DISPATCH).bytes().unsignedLong(38*4));assertEquals(0x20D136,source.swingData().mapping(CdR4SolidMover.Mapping.SWING));assertEquals(0x20CCE4,source.switchData().mapping());assertSame(source.swingData(),source.swingData());assertSame(source.switchData(),source.switchData());}
 @Test void fourAppendedFiniteViewsMatchTheOriginalMmdAndOldOrdinalsRemain(){assertEquals(69,CdProgrammeObjectSource.Table.SWING_MAPPINGS.ordinal());assertEquals(73,CdProgrammeObjectSource.Table.values().length);for(var t:List.of(CdProgrammeObjectSource.Table.SWING_MAPPINGS,CdProgrammeObjectSource.Table.SWING_MAP_STORE,CdProgrammeObjectSource.Table.SWITCH_MAPPINGS,CdProgrammeObjectSource.Table.SWITCH_MAP_STORE)){var v=source.view(t);assertArrayEquals(original.readFile(t.fileOffset(),t.length()),v.bytes().copy());assertEquals(t.sha256(),CdR11aProfile.sha256(v.bytes().copy()));}}
 @Test void countedRootsKeepAllThreeSwingAndTwoSwitchFramesWithoutWrongPointerAdmission(){for(int n=0;n<3;n++)assertInstanceOf(CdObjectDrawQueue.FrameMapping.class,source.mappings().resolve(0x20D136,false,n));for(int n=0;n<2;n++)assertInstanceOf(CdObjectDrawQueue.FrameMapping.class,source.mappings().resolve(0x20CCE4,false,n));assertThrows(UnsupportedOperationException.class,()->source.mappings().resolve(0x20D136,false,3));assertThrows(UnsupportedOperationException.class,()->source.mappings().resolve(0x20CCE4,false,2));assertThrows(UnsupportedOperationException.class,()->source.mappings().resolve(0x20D138,false,0));}
 @Test void irrelevantBorrowedTablesAndAddressesNeverAcquireDefaults(){var d=source.swingData();assertThrows(UnsupportedOperationException.class,()->d.mapping(CdR4SolidMover.Mapping.BLOCK));assertThrows(UnsupportedOperationException.class,()->d.table(CdR4SolidMover.Table.BLOCK_SIZES));assertThrows(UnsupportedOperationException.class,()->d.address(CdR4SolidMover.Address.SAVED_FLAGS));assertEquals(com.openggf.game.soniccd.objects.r4.CdR4SwitchBank.BASE_WORD,source.switchData().switchBaseWord());}
}
